 const filteredItems=items.filter(item=>item.value===candidate||item.label.toLocaleLowerCase().includes(candidateSearch.toLocaleLowerCase()));
 const selected=candidates.find(a=>a.candidateId===candidate);
 const proposals=[...new Map(activities.filter(a=>a.playerId===owner&&a.candidateId===candidate&&a.stage==="提案"&&a.recordId).map(a=>[a.recordId,a])).values()];
